    components = []
    component_positions = []

    def in_bounds(r, c):
        return 0 <= r < n and 0 <= c < m

    def get_component(r0, c0):
        component = []
        queue = [(r0, c0)]
        visited[r0][c0] = True

        while queue:
            r, c = queue.pop(0)
            component.append((r, c))

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if in_bounds(nr, nc) and not visited[nr][nc] and grid[nr][nc] == '.':
                    visited[nr][nc] = True
                    queue.append((nr, nc))

        return component

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                comp = get_component(r, c)
                component_positions.append(comp)

