        # Try to fill remaining positions with smallest characters
        for char_code in range(ord('a'), ord('z') + 1):
            char = chr(char_code)
            current.append(char)
            result = smallest_completion_from(idx + 1, current, True)
            if result:
                return True
            current.pop()
        return False

