            prefix_chars.append(char)
            if try_with_prefix(prefix_chars, start_idx + 1, is_greater_than_original):
                return True
            prefix_chars.pop()
        return False

    # Try both approaches: starting from s and modifying at each position

    # First try the original string s
    if check(list(s)):
        return s

    # Try systematically: at each position i, try to upgrade s[i] and complete
    for i in range(n):
        prefix = list(s[:i])
