def solution(input_str: str) -> str:
    """
    Find non-crossing matching between spaceships and bases.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    spaceships = []
    bases = []

    idx = 1
    for i in range(n):
        x, y = map(int, lines[idx].split())
        spaceships.append((float(x), float(y)))
        idx += 1

    for i in range(n):
        x, y = map(int, lines[idx].split())
        bases.append((float(x), float(y)))
        idx += 1

    # Compute centroid of all points
    all_x = [s[0] for s in spaceships] + [b[0] for b in bases]
    all_y = [s[1] for s in spaceships] + [b[1] for b in bases]
    cx = sum(all_x) / (2 * n)
    cy = sum(all_y) / (2 * n)

    def get_angle(p):
        return math.atan2(p[1] - cy, p[0] - cx)

    # Sort spaceships and bases by angle around centroid
    ship_indices = sorted(range(n), key=lambda i: get_angle(spaceships[i]))
    base_indices = sorted(range(n), key=lambda i: get_angle(bases[i]))

    # Match in angular order
    result = [0] * n
    for i in range(n):
        result[ship_indices[i]] = base_indices[i] + 1  # 1-indexed

    return '\n'.join(map(str, result))


