def is_geometric(arr):
    if len(arr) <= 2:
        return True
    # Handle the case where first element is zero - if we have [0, 0, 0, ...] it's still GP
    # But [0, 1, 2] is not
    if arr[0] == 0:
        # If first element is 0, all subsequent elements must be 0 for it to be GP
        for x in arr[1:]:
            if x != 0:
                return False
        return True

    # Calculate ratio from first two elements
    ratio = None
    is_rat = True
    for i in range(len(arr) - 1):
        if arr[i] == 0:
            # If any element is 0, all remaining must be 0
            if i == 0:
                # First element is 0, check rest
                if arr[i+1] != 0 or any(x != 0 for x in arr[i+1:]):
                    return False
                else:
                    continue
            else:
                # Some element before this is 0, but we didn't return False already
                # So we have a 0 appearing in middle - not GP
                return False
        if arr[i+1] != 0 and ratio is None:
            ratio = arr[i+1] / arr[i]
        elif arr[i+1] == 0:
            if arr[i] == 0:
                continue  # 0/0, still valid GP if all are 0
            else:
                # We had a non-zero followed by 0, ratio would be 0
                # Check if all subsequent are 0
                if any(x != 0 for x in arr[i+2:]):
                    return False

    return is_rat

