MOD = 10**9 + 7

def mat_mul(A, B, size=4):
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for k in range(size):
            if A[i][k] == 0:
                continue
            for j in range(size):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p, size=4):
    if p == 0:
        return [[1 if i == j else 0 for j in range(size)] for i in range(size)]

    result = mat_pow(A, p // 2, size)
    result = mat_mul(result, result, size)

    if p % 2 == 1:
        result = mat_mul(result, A, size)

    return result

