from collections import defaultdict

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, u, v, capacity):
        self.graph[u].append([v, len(self.graph[v]), capacity])
        self.graph[v].append([u, len(self.graph[u]) - 1, 0])

    def bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v, rev, cap in self.graph[u]:
                if level[v] == -1 and cap > 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[t] != -1

    def dfs(self, u, t, flow, ptr, level):
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, rev, cap = self.graph[u][i]
            if level[v] == level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr, level)
                if pushed > 0:
                    self.graph[u][i][2] -= pushed
                    self.graph[v][rev][2] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr, list(range(self.n)))
                if pushed == 0:
                    break
                flow += pushed
        return flow

