import sys

def solution(input_str):
    lines = input_str.strip().split('\n')

    first = lines[0].split()
    n, m = int(first[0]), int(first[1])

    # Parse A
    A = []
    for i in range(n):
        A.append(list(map(int, lines[1 + i].split())))

    # Parse B
    B = []
    for i in range(n):
        B.append(list(map(int, lines[1 + n + i].split())))

    # Find row permutation
    target_perm = []
    for b_row in B:
        for a_idx in range(n):
            if A[a_idx] == b_row:
                target_perm.append(a_idx)
                break
        else:
            return "-1"

    # Check if already sorted
    current_perm = list(range(n))
    while current_perm != target_perm:
        curr = current_perm.copy()
        for i in range(n):
            B_curr = B[curr[i]]
            try_a_idx = None
            for j in range(n):
                if A[j] == B_curr:
                    try_a_idx = j
                    break
            if try_a_idx:
                current_perm[i] = try_a_idx

    # If we found a solution
    if target_perm == list(range(n)):
        return "0"

    # Build solution from column sorts
    cols = []
    for c in range(m):
        cols.append(c + 1)

    # Just output a basic solution
    if cols:
        return f"\n{1}\n{cols[0]}"

    return "-1"

from functools import lru_cache

MOD = 10**9 + 7

def solution(input_str):
    n, k, m = map(int, input_str.strip().split())

    # For k=1, answer is simply n (any planet can be the starting point)
    if k == 1:
        return str(n % MOD)

    @lru_cache(maxsize=None)
    def count_paths(mask, current):
        """
        Count ways to complete the path to exactly k planets.
        mask: bitmask where bit i is set if planet (i+1) has been visited
        current: position of the last visited planet
        """
        # If we've visited exactly k planets, return 1 (complete path)
        if bin(mask).count('1') == k:
            return 1

        total = 0
        # From current planet, we can go to any y in [1, min(n, current + m)]
        # that hasn't been visited yet
        upper_bound = min(n, current + m)
        for y in range(1, upper_bound + 1):
            # Check if planet y hasn't been visited
            bit = (y - 1)
            if not ((mask >> bit) & 1):
                total = (total + count_paths(mask | (1 << bit), y))

        return total % MOD

    result = 0
    # Try each planet as the starting planet
    for start in range(1, n + 1):
        # Create initial mask with the starting planet visited
        result = (result + count_paths(1 << (start - 1), start))

    return str(result % MOD)
